window.docContents[154].resolve({"/Aula-1___-Motiva______o-e-L___gica-Proposicional/Exemplos-Resolvidos/#Verifica______o-Formal-de-Software--Aula-1___-Motiva______o-e-L___gica-Proposicional--Exemplos-Resolvidos--Modus-Ponens":{"contents":"Uma implicação e o seu antecedente, ambos projetados da conjunção, combinam-se por →E para dar o consequente.\n\n   [(P→Q)∧P]           [(P→Q)∧P]\n  ───────────── ∧E₁    ───────────── ∧E₂\n      P → Q                  P\n    ────────────────────────────── →E\n                 Q\n   ──────────────────────────────── →I\n        (P → Q) ∧ P → Q\n\n\nexample (P Q : Prop) : (P → Q) ∧ P → Q :=\n  fun h => h.left h.right\n\n\nexample (P Q : Prop) : (P → Q) ∧ P → Q := by\n  intro h\n  apply h.left\n  exact h.right\n\n\n","context":"Verificação Formal de Software\u0009Aula 1: Motivação e Lógica Proposicional\u0009Exemplos Resolvidos","header":"1.8.3. Modus Ponens","id":"/Aula-1___-Motiva______o-e-L___gica-Proposicional/Exemplos-Resolvidos/#Verifica______o-Formal-de-Software--Aula-1___-Motiva______o-e-L___gica-Proposicional--Exemplos-Resolvidos--Modus-Ponens"}});